function validate([words, queries]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100000) return 'words needs 1 to 100000 strings.';
  let total = 0;
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 40) return 'Each word has 1 to 40 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use only lowercase English letters.';
    total += word.length;
  }
  if (total > 300000) return 'The words may have at most 300000 letters in total.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 100000 pairs.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [l, r].';
    const [l, r] = query;
    if (!Number.isInteger(l) || !Number.isInteger(r) || l < 0 || l > r || r >= words.length) return 'Each query needs 0 <= l <= r < words.length.';
  }
  return null;
}

