function vowelStrings(words, queries) {
  const pattern = /^[aeiou]$|^[aeiou][a-z]*[aeiou]$/;
  return queries.map(([l, r]) => {
    let count = 0;
    for (let k = l; k <= r; k++) if (pattern.test(words[k])) count++;
    return count;
  });
}

