function generate(rand, size) {
  const letters = 'aeioubcdxyz';
  const word = (maxLength) => {
    const length = 1 + Math.floor(rand() * maxLength);
    let text = '';
    for (let k = 0; k < length; k++) text += letters[Math.floor(rand() * letters.length)];
    return text;
  };
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 6);
  const q = size === 'large' ? 2000 : 1 + Math.floor(rand() * 6);
  const words = Array.from({ length: n }, () => word(size === 'large' ? 5 : 4));
  const queries = Array.from({ length: q }, () => {
    const a = Math.floor(rand() * n);
    const b = Math.floor(rand() * n);
    return [Math.min(a, b), Math.max(a, b)];
  });
  return [words, queries];
}
